def has_cycle(adj, n, skip_edge=None):
    color = [0] * (n + 1)  # 0=white, 1=gray, 2=black

    def dfs(u):
        color[u] = 1
        for v in adj[u]:
            if skip_edge and (u, v) == skip_edge:
                continue
            if color[v] == 1:
                return True
            if color[v] == 0:
                if dfs(v):
                    return True
        color[u] = 2
        return False

    for i in range(1, n + 1):
        if color[i] == 0:
            if dfs(i):
                return True
    return False

