    n = input().strip()
    digits = list(n)

    best = float('inf')

    endings = [(0,0), (2,5), (5,0), (7,5)]

    for (d1, d2) in endings:
        d = digits[:]
        moves = 0

        # Find rightmost d2, move to last position
        pos2 = -1
        for i in range(len(d)-1, -1, -1):
            if int(d[i]) == d2:
                pos2 = i
                break
        if pos2 == -1:
            continue

        # Move d[pos2] to end
        for i in range(pos2, len(d)-1):
            d[i], d[i+1] = d[i+1], d[i]
            moves += 1

        # Find rightmost d1 in d[0..len-2], move to second last
        pos1 = -1
        for i in range(len(d)-2, -1, -1):
            if int(d[i]) == d1:
                pos1 = i
                break
        if pos1 == -1:
            continue

        # Move d[pos1] to position len-2
        for i in range(pos1, len(d)-2):
            d[i], d[i+1] = d[i+1], d[i]
            moves += 1

        # Handle leading zeros
        if d[0] == '0':
            # Find first non-zero digit
            first_nonzero = -1
            for i in range(len(d)):
                if d[i] != '0':
                    first_nonzero = i
                    break
            if first_nonzero == -1:
                # All zeros - impossible (but n >= 1 so this shouldn't happen unless n=0)
                continue
            # Bubble d[first_nonzero] to front
            for i in range(first_nonzero, 0, -1):
                d[i], d[i-1] = d[i-1], d[i]
                moves += 1

        best = min(best, moves)

    if best == float('inf'):
        print(-1)
    else:
        print(best)

