from collections import deque

def solve():
    n = int(input())
    s = input().strip()
    r = s.count('R')
    g = s.count('G')
    b = s.count('B')

    visited = set()
    queue = deque()
    queue.append((r, g, b))
    visited.add((r, g, b))

    final = set()

    while queue:
        r, g, b = queue.popleft()
        if r + g + b == 1:
            if r == 1: final.add('R')
            if g == 1: final.add('G')
            if b == 1: final.add('B')
            continue

        # Op2: same color
        if r >= 2: 
            state = (r-1, g, b)
            if state not in visited: visited.add(state); queue.append(state)
        if g >= 2:
            state = (r, g-1, b)
            if state not in visited: visited.add(state); queue.append(state)
        if b >= 2:
            state = (r, g, b-1)
            if state not in visited: visited.add(state); queue.append(state)

        # Op1: different colors
        if r >= 1 and g >= 1:
            state = (r-1, g-1, b+1)
            if state not in visited: visited.add(state); queue.append(state)
        if r >= 1 and b >= 1:
            state = (r-1, g+1, b-1)
            if state not in visited: visited.add(state); queue.append(state)
        if g >= 1 and b >= 1:
            state = (r+1, g-1, b-1)
            if state not in visited: visited.add(state); queue.append(state)

    result = ''.join(sorted(final))
    print(result)

