def count_black(r1, r2, c1, c2):
    if r1 > r2 or c1 > c2:
        return 0
    rows = r2 - r1 + 1
    cols = c2 - c1 + 1
    total = rows * cols
    # black if (r+c) even
    # count depends on parity of r1+c1
    if (r1 + c1) % 2 == 0:
        return (total + 1) // 2
    else:
        return total // 2

