def mat_mul(A, B, mod):
    return [[(A[0][0]*B[0][0] + A[0][1]*B[1][0]) % mod, (A[0][0]*B[0][1] + A[0][1]*B[1][1]) % mod],
            [(A[1][0]*B[0][0] + A[1][1]*B[1][0]) % mod, (A[1][0]*B[0][1] + A[1][1]*B[1][1]) % mod]]

def mat_pow(M, n, mod):
    result = [[1,0],[0,1]]
    while n:
        if n & 1: result = mat_mul(result, M, mod)
        M = mat_mul(M, M, mod)
        n >>= 1
    return result

def fib(n, mod):
    if n == 0: return 0
    M = [[1,1],[1,0]]
    return mat_pow(M, n, mod)[0][1]
